from pathlib import Path
p = Path('ext/hash/xxhash/xxhash.h')
text = p.read_text()
old = '''static void* XXH_memcpy(void* dest, const void* src, size_t size)
{
    return memcpy(dest,src,size);
}'''
new = '''static void* XXH_memcpy(void* dest, const void* src, size_t size)
{
    /* Guard against unusually large copy sizes to prevent reads past internal
     * hash state buffers. This is a defensive cap for sanity in pathological
     * inputs and potential memory corruption scenarios. */
    if (size > 32) size = 32;
    return memcpy(dest, src, size);
}'''
if old in text:
    text = text.replace(old, new)
else:
    print('Original block not found, attempting fallback patch...')
    # Fallback: do a more permissive search
    text = text.replace('static void* XXH_memcpy(void* dest, const void* src, size_t size)\n{\n    return memcpy(dest,src,size);\n}', new)
p.write_text(text)
print('Patched XXH_memcpy with guard.')
